  "sets": {
    "I": "Set of all product SKUs (indexed by i), derived from the 'Product_SKU' column in the CSV."
  },
  "parameters": {
    "p_i": "Sale price per unit for SKU i (from 'Sale_Price_Per_Unit').",
    "c_i": "Material cost per unit for SKU i (from 'Material_Cost_Per_Unit').",
    "m_i": "Molding minutes required per unit for SKU i (from 'Molding_Mins_Req').",
    "a_i": "Assembly minutes required per unit for SKU i (from 'Assembly_Mins_Req').",
    "d_i": "Maximum market capacity for SKU i (from 'Max_Market_Capacity').",
    "C_molding": "Total available molding minutes = 10000 (constant).",
    "C_assembly": "Total available assembly minutes = 10000 (constant)."
  },
  "decision_variables": {
    "x_i": "Production quantity (units) for SKU i. Type: LpContinuous (can be changed to LpInteger if discrete units are required). Domain: x_i >= 0."
  },
  "objective_function": {
    "mathematical_formulation": "Maximize $Z = \\sum_{i \\in I} (p_i - c_i) x_i$",
    "description": "Maximize total profit by summing the unit profit (sale price minus material cost) across all SKUs multiplied by their respective production quantities.",
    "pulp_expression": "prob += pulp.lpSum([(p[i] - c[i]) * x[i] for i in I])"
  },
  "constraints": [
    {
      "name": "Molding Time Capacity",
      "mathematical_formulation": "$\\sum_{i \\in I} m_i x_i \\leq C_{molding}$",
      "description": "The total molding time consumed by producing all SKUs must not exceed the available 10000 minutes.",
      "pulp_expression": "prob += pulp.lpSum([m[i] * x[i] for i in I]) <= C_molding"
    },
    {
      "name": "Assembly Time Capacity",
      "mathematical_formulation": "$\\sum_{i \\in I} a_i x_i \\leq C_{assembly}$",
      "description": "The total assembly time consumed by producing all SKUs must not exceed the available 10000 minutes.",
      "pulp_expression": "prob += pulp.lpSum([a[i] * x[i] for i in I]) <= C_assembly"
    },
    {
      "name": "Market Capacity per SKU",
      "mathematical_formulation": "$x_i \\leq d_i \\quad \\forall i \\in I$",
      "description": "Production quantity for each individual SKU cannot exceed its respective maximum market demand/capacity.",
      "pulp_expression": "for i in I: prob += x[i] <= d[i]"
    },
    {
      "name": "Non-negativity",
      "mathematical_formulation": "$x_i \\geq 0 \\quad \\forall i \\in I$",
      "description": "Production quantities cannot be negative. Enforced during variable creation via lowBound=0.",
      "pulp_expression": "x = {i: pulp.LpVariable(f'x_{i}', lowBound=0, cat='Continuous') for i in I}"
    }
  ],
  "complete_pulp_implementation_guide": {
    "imports": "import pulp as pulp",
    "problem_initialization": "prob = pulp.LpProblem('Production_Planning_MILP', pulp.LpMaximize)",
    "data_loading": "I = df['Product_SKU'].tolist()\np = dict(zip(df['Product_SKU'], df['Sale_Price_Per_Unit']))\nc = dict(zip(df['Product_SKU'], df['Material_Cost_Per_Unit']))\nm = dict(zip(df['Product_SKU'], df['Molding_Mins_Req']))\na = dict(zip(df['Product_SKU'], df['Assembly_Mins_Req']))\nd = dict(zip(df['Product_SKU'], df['Max_Market_Capacity']))\nC_molding = 10000\nC_assembly = 10000",
    "variable_creation": "x = {i: pulp.LpVariable(f'x_{i}', lowBound=0, cat='Continuous') for i in I}",
    "objective_definition": "prob += pulp.lpSum([(p[i] - c[i]) * x[i] for i in I])",
    "constraint_definition": [
      "prob += pulp.lpSum([m[i] * x[i] for i in I]) <= C_molding",
      "prob += pulp.lpSum([a[i] * x[i] for i in I]) <= C_assembly",
      "for i in I: prob += x[i] <= d[i]"
    ],
    "solving_and_output": "prob.solve()\nprint(f'Status: {pulp.LpStatus[prob.status]}')\nfor i in I: print(f'Produce {i}: {x[i].varValue} units')"
  }
}
